    nonisolated func map(_ value: ErmaoShared.ManagementEventPage) -> LogPage { LogPage(events: value.events.map { ManagementLogEvent(id: $0.id, timestamp: date($0.createdAt) ?? .distantPast, level: $0.level.lowercased() == "error" ? .error : $0.level.lowercased() == "warning" ? .warning : .information, source: $0.source, summary: $0.message, correlationID: $0.metadata["correlationId"], target: $0.targetId) }, usedBytes: value.storage.sizeBytes, limitBytes: value.storage.maximumBytes) }
    nonisolated func csvField(_ value: String) -> String { "\"" + value.replacingOccurrences(of: "\"", with: "\"\"") + "\"" }
